<?php
declare(strict_types=1);
require_once __DIR__.'/Support/ReviewedLocalFixture.php';
use DigiForge\Portal\ReviewedAcceptanceContract as Contract;
use DigiForge\Portal\ApprovedAcceptancePolicy as Policy;
final class ApprovedAcceptancePolicyTest extends WP_UnitTestCase {
 private array $actors;
 protected function setUp():void {parent::setUp();DigiForge\Core\Activator::activate();DigiForge\Core\Settings::protectProduction();$this->actors=ReviewedLocalFixture::actors('personalized_pod');}
 private function ref():array{return ['shop_key'=>'personalized_pod','reference'=>'local://synthetic/population-v1','sha256'=>hash('sha256','synthetic-only')];}
 private function definition(string $criterion):array{return ['policy'=>Policy::rules($criterion),'environment'=>'sandbox','subject'=>['scope'=>'PRODUCT_VERSION','product_id'=>'p1','product_version'=>'v1','supplier_id'=>null],'period_start'=>'2026-01-01T00:00:00Z','period_end'=>'2026-02-01T00:00:00Z','source_records'=>[$this->ref()],'observations'=>null];}
 private function input(string $criterion,array $d):array{return ['version'=>2,'criterion'=>$criterion,'scope'=>'synthetic-scope','workflow'=>'product_factory','definition'=>$d];}
 private function approve(string $criterion,array $d):array {$p=Contract::propose('personalized_pod',$this->input($criterion,$d),time()-1,time()+600,wp_generate_uuid4(),0);self::assertNotWPError($p);wp_set_current_user($this->actors['reviewer']);$a=Contract::decide('personalized_pod',$criterion,'synthetic-scope',$p['revision'],$p['proposal_hash'],'APPROVED',wp_generate_uuid4());self::assertNotWPError($a);wp_set_current_user($this->actors['author']);return $a;}
 public static function criteria():array{return array_map(static fn($c)=>[$c],Contract::criteria());}
 /** @dataProvider criteria */
 public function testTenApprovedRulesUseIndependentReviewAndMissingEvidenceStaysUnknown(string $c):void {$d=$this->definition($c);if($c==='BP-portal-17-supplier-performance')$d['subject']=['scope'=>'SUPPLIER','product_id'=>null,'product_version'=>null,'supplier_id'=>'s1'];if($c==='BP-portal-17-shop-performance')$d['subject']=['scope'=>'SHOP','product_id'=>null,'product_version'=>null,'supplier_id'=>null];self::assertSame('UNKNOWN',Contract::evaluate('personalized_pod',$c,'synthetic-scope')['state']);$this->approve($c,$d);$out=Contract::evaluate('personalized_pod',$c,'synthetic-scope');self::assertSame('UNKNOWN',$out['state']);self::assertSame('UNVERIFIED',$out['evidence_state']);self::assertFalse($out['external_execution_authorized']);self::assertFalse($out['publishing_allowed']);}
 private function row(string $kind,string $id):array {return ['kind'=>$kind,'id'=>$id,'shop_key'=>'personalized_pod','product_id'=>'p1','product_version'=>'v1','supplier_id'=>'s1','occurred_at'=>'2026-01-02T00:00:00Z','source_reference'=>$this->ref()['reference']]+match($kind){'VISIT'=>[], 'ORDER'=>['visit_id'=>'visit1'], 'UNIT'=>['order_id'=>'order1','on_time'=>true,'exception'=>false,'defect'=>'CONFIRMED'],default=>[]};}
 private function metrics():array{return ['coverage'=>['visits'=>true,'orders'=>true,'units'=>true,'defects'=>true],'records'=>[$this->row('VISIT','visit1'),$this->row('VISIT','visit2'),$this->row('ORDER','order1'),$this->row('UNIT','unit1'),$this->row('UNIT','unit1')]];}
 public function testReviewedConversionAndDefectRatesDeduplicateAndKeepProvenance():void {foreach(['BP-portal-17-conversion','BP-portal-17-defect-quality']as $i=>$c){$d=$this->definition($c);$d['observations']=$this->metrics();$this->approve($c,$d);$o=Contract::evaluate('personalized_pod',$c,'synthetic-scope');self::assertSame('LOCAL_CALCULATED',$o['state']);self::assertSame($i===0?50.0:100.0,$o['metrics'][$i===0?'conversion_percent':'defect_percent']['value']);self::assertSame(1,$o['metrics']['fulfilled_units']['value']);self::assertSame(1,$o['metrics']['orders']['value']);self::assertArrayNotHasKey('profit',$o);self::assertEquals([$this->ref()],$o['source_records']);}}
 public function testMissingDenominatorAndUnreviewedDefectsNeverBecomeZero():void {$c='BP-portal-17-product-performance';$d=$this->definition($c);$d['observations']=$this->metrics();$d['observations']['coverage']['visits']=false;$d['observations']['records'][3]['defect']='UNREVIEWED';array_pop($d['observations']['records']);$this->approve($c,$d);$o=Contract::evaluate('personalized_pod',$c,'synthetic-scope');self::assertNull($o['metrics']['conversion_percent']['value']);self::assertSame('UNKNOWN',$o['metrics']['conversion_percent']['state']);self::assertNull($o['metrics']['defect_percent']['value']);}
 public function testConflictingUnitsForeignShopStaleVersionAndUnattributedOrdersReject():void {$c='BP-portal-17-conversion';foreach(['shop_key'=>'digital','product_version'=>'v2','occurred_at'=>'2026-02-01T00:00:00Z','source_reference'=>'local://missing']as $k=>$v){$d=$this->definition($c);$d['observations']=$this->metrics();$d['observations']['records'][0][$k]=$v;self::assertWPError(Contract::propose('personalized_pod',$this->input($c,$d),time()-1,time()+600,wp_generate_uuid4(),0));}$d=$this->definition($c);$d['observations']=$this->metrics();$d['observations']['records'][4]['defect']='CLEARED';self::assertWPError(Contract::propose('personalized_pod',$this->input($c,$d),time()-1,time()+600,wp_generate_uuid4(),0));$d['observations']=$this->metrics();$d['observations']['records'][2]['visit_id']='missing';self::assertWPError(Contract::propose('personalized_pod',$this->input($c,$d),time()-1,time()+600,wp_generate_uuid4(),0));}
 public function testRevokedReviewFutureExpiryAndRulesTamperingFailClosed():void {$c='BP-portal-17-conversion';$d=$this->definition($c);$d['observations']=$this->metrics();$a=$this->approve($c,$d);$before=Contract::evaluate('personalized_pod',$c,'synthetic-scope');self::assertSame($before,Contract::evaluate('personalized_pod',$c,'synthetic-scope'));wp_set_current_user($this->actors['reviewer']);self::assertNotWPError(Contract::decide('personalized_pod',$c,'synthetic-scope',$a['revision'],$a['proposal_hash'],'REVOKED',wp_generate_uuid4()));self::assertSame('UNKNOWN',Contract::evaluate('personalized_pod',$c,'synthetic-scope')['state']);wp_set_current_user($this->actors['author']);$d['policy']['formula']='invented weighted score';self::assertWPError(Contract::propose('personalized_pod',$this->input($c,$d),time()-1,time()+600,wp_generate_uuid4(),$a['revision']));self::assertWPError(Contract::evaluate('digital',$c,'synthetic-scope'));}
 public function testPortalReturnsReadOnlyScopedEvaluationAndWrongEnvironmentStaysUnknown():void {
  $c='BP-portal-17-conversion';$d=$this->definition($c);$d['observations']=$this->metrics();$this->approve($c,$d);
  (new DigiForge\REST\ReviewedContractsController())->register();(new DigiForge\Security\ShopAccessRestGuard())->register();do_action('rest_api_init');
  $request=new WP_REST_Request('GET','/digiforge/v1/reviewed-contracts/personalized_pod/acceptance');$request->set_query_params(['criterion'=>$c,'scope'=>'synthetic-scope','environment'=>'sandbox']);$response=rest_get_server()->dispatch($request);self::assertSame(200,$response->get_status());$data=$response->get_data();self::assertSame(50.0,$data['policy_evaluation']['metrics']['conversion_percent']['value']);self::assertSame('UNVERIFIED',$data['evidence_state']);self::assertSame('UNKNOWN',$data['value_state']);self::assertArrayNotHasKey('observations',$data['policy_evaluation']);
  $request->set_query_params(['criterion'=>$c,'scope'=>'synthetic-scope','environment'=>'production']);self::assertSame('UNKNOWN',rest_get_server()->dispatch($request)->get_data()['policy_evaluation']['state']);wp_set_current_user(0);self::assertSame(401,rest_get_server()->dispatch($request)->get_status());
 }
 public function testFeedbackCorrectionsPreserveAttributionAndDistinguishAllegations():void {
  $c='BP-quality-feedback';$d=$this->definition($c);$r=['feedback_id'=>'f1','order_id'=>'order1','shop_key'=>'personalized_pod','product_id'=>'p1','product_version'=>'v1','supplier_id'=>'s1','occurred_at'=>'2026-01-02T00:00:00Z','source_reference'=>$this->ref()['reference'],'revision'=>1,'previous_sha256'=>null,'status'=>'ALLEGED'];$next=$r;$next['revision']=2;$next['previous_sha256']=hash('sha256',DigiForge\Listings\Validator::canonicalJson($r));$next['status']='CONFIRMED';$d['observations']=[$r,$next];$this->approve($c,$d);$o=Contract::evaluate('personalized_pod',$c,'synthetic-scope');self::assertSame('CONFIRMED',$o['feedback'][0]['status']);self::assertSame(2,$o['feedback'][0]['correction_revision']);self::assertFalse($o['purpose_verified']);
  foreach(['previous_sha256'=>str_repeat('f',64),'order_id'=>'different','status'=>'AUTOMATIC_DEFECT','comment'=>'private customer text']as $k=>$v){$bad=$d;$bad['observations'][1][$k]=$v;self::assertFalse(Policy::valid('personalized_pod',$c,$bad));}
 }
 public function testSeamPanelRequiresExactBleedGeometryAndReviewedParityDeclarations():void {
  $c='BP-seam-panel-render';$d=$this->definition($c);$g=['width_px'=>100,'height_px'=>100,'dpi'=>100,'qa_geometry'=>['min_image_dpi'=>100,'safe_zone'=>['x'=>10,'y'=>10,'width'=>80,'height'=>80],'seam_exclusions'=>[],'bleed'=>['trim_box'=>['x'=>5,'y'=>5,'width'=>90,'height'=>90],'margins_px'=>['left'=>5,'right'=>5,'top'=>5,'bottom'=>5]]]];
  $d['observations']=['template_sha256'=>hash('sha256','v1'),'geometry_sha256'=>hash('sha256',DigiForge\Listings\Validator::canonicalJson(['front'=>$g])),'panels'=>[['id'=>'front','artifact_sha256'=>hash('sha256','art'),'preview_sha256'=>hash('sha256','art'),'geometry'=>$g]],'alignment_review_sha256'=>hash('sha256','review')];$this->approve($c,$d);self::assertSame('MATCHED_REVIEWED_DECLARATION',Contract::evaluate('personalized_pod',$c,'synthetic-scope')['state']);$bad=$d;$bad['observations']['panels'][0]['geometry']['qa_geometry']['bleed']['margins_px']['left']=6;self::assertFalse(Policy::valid('personalized_pod',$c,$bad));$bad=$d;$bad['observations']['panels'][0]['preview_sha256']=hash('sha256','different');self::assertSame('BLOCKED',Policy::evaluate('personalized_pod',$c,$bad)['state']);
 }
 public function testSupplierAndShopMetricsRemainSeparateWithExplicitScope():void {
  foreach(['BP-portal-17-supplier-performance','BP-portal-17-shop-performance']as $c){$d=$this->definition($c);$d['subject']=$c==='BP-portal-17-shop-performance'?['scope'=>'SHOP','product_id'=>null,'product_version'=>null,'supplier_id'=>null]:['scope'=>'SUPPLIER','product_id'=>null,'product_version'=>null,'supplier_id'=>'s1'];$d['observations']=$this->metrics();$this->approve($c,$d);$o=Contract::evaluate('personalized_pod',$c,'synthetic-scope');self::assertSame('LOCAL_COUNTS',$o['metrics']['timeliness']['state']);self::assertSame(1,$o['metrics']['timeliness']['on_time_units']);self::assertSame(0,$o['metrics']['exceptions']['exception_units']);self::assertArrayNotHasKey('score',$o['metrics']);self::assertArrayNotHasKey('profit',$o['metrics']);}
 }
 public function testEmptyCompleteDenominatorIsUnknownWhileKnownZeroOrdersStayZero():void {$c='BP-portal-17-conversion';$d=$this->definition($c);$d['observations']=['coverage'=>array_fill_keys(['visits','orders','units','defects'],true),'records'=>[]];$this->approve($c,$d);$o=Contract::evaluate('personalized_pod',$c,'synthetic-scope');self::assertSame(0,$o['metrics']['orders']['value']);self::assertNull($o['metrics']['conversion_percent']['value']);self::assertNull($o['metrics']['defect_percent']['value']);self::assertFalse($o['external_execution_authorized']);}
 public function testSupplierDeclarationsCannotCertifyReadiness():void {$c='BP-portal-7-supplier-readiness';$d=$this->definition($c);$d['observations']=array_fill_keys(['product','supplier','variant','geometry','rights','fulfillment','review'],hash('sha256','declaration-only'));$this->approve($c,$d);$o=Contract::evaluate('personalized_pod',$c,'synthetic-scope');self::assertSame('REVIEW_REQUIRED',$o['state']);self::assertFalse($o['supplier_approved']);self::assertFalse($o['production_authorized']);}
 public function testDeterministicFirstAndAiRequiresEvidenceWithoutExecution():void {$c='BP-ai-value-routing';$d=$this->definition($c);$d['observations']=['deterministic_available'=>true,'requested'=>'AI','permitted'=>true,'provenance_sha256'=>null,'benefit_review_sha256'=>null];$this->approve($c,$d);$o=Contract::evaluate('personalized_pod',$c,'synthetic-scope');self::assertSame('DETERMINISTIC',$o['recommendation']);self::assertFalse($o['ai_execution_allowed']);}
 public function testSpellingMetadataRejectsAlterationOverflowAndUnsupportedGlyphs():void {$c='BP-template-qa-spelling';$d=$this->definition($c);$d['observations']=['template_sha256'=>hash('sha256','v2'),'locale'=>'en-US','text_sha256'=>hash('sha256','Mira & Léon'),'automated_review_sha256'=>hash('sha256','automated'),'human_review_sha256'=>hash('sha256','human'),'family_name_code_points'=>48,'established_code_points'=>0,'glyphs_supported'=>true,'overflow'=>false,'auto_shrink'=>false,'normalization'=>'NONE'];$this->approve($c,$d);self::assertSame('MATCHED_REVIEWED_DECLARATION',Contract::evaluate('personalized_pod',$c,'synthetic-scope')['state']);self::assertWPError(Contract::matchesText('personalized_pod','synthetic-scope','Mira & Léon','en-US'));self::assertWPError(Contract::matchesText('personalized_pod','synthetic-scope','Mira & Léon','en-US',hash('sha256','wrong-version')));self::assertTrue(Contract::matchesText('personalized_pod','synthetic-scope','Mira & Léon','en-US',hash('sha256','v2')));self::assertWPError(Contract::matchesText('personalized_pod','synthetic-scope','MIRA & LÉON','en-US'));foreach(['family_name_code_points'=>49,'auto_shrink'=>true,'normalization'=>'NFC']as $k=>$v){$bad=$d;$bad['observations'][$k]=$v;self::assertWPError(Contract::propose('personalized_pod',$this->input($c,$bad),time()-1,time()+600,wp_generate_uuid4(),0));}}
}
